<?php
if(!defined('ABSPATH'))exit;
function dgs_school_schedule_table(){global $wpdb;return $wpdb->prefix.'dgs_timetables';}
add_action('init',function(){if(get_option('dgs_timetable_schema')==='1')return;global $wpdb;require_once ABSPATH.'wp-admin/includes/upgrade.php';$table=dgs_school_schedule_table();$cc=$wpdb->get_charset_collate();dbDelta("CREATE TABLE $table (
 id bigint(20) unsigned NOT NULL AUTO_INCREMENT,
 class_id bigint(20) unsigned NOT NULL,
 periods longtext NOT NULL,
 cells longtext NOT NULL,
 events longtext NOT NULL,
 revision bigint(20) unsigned NOT NULL DEFAULT 1,
 updated_by bigint(20) unsigned NOT NULL,
 PRIMARY KEY  (id),
 UNIQUE KEY class_schedule (class_id)
 ) ENGINE=InnoDB $cc;");if($wpdb->get_var($wpdb->prepare('SHOW TABLES LIKE %s',$wpdb->esc_like($table)))===$table)update_option('dgs_timetable_schema','1',false);},15);
function dgs_school_clock($raw){if(!is_string($raw))return '';$raw=dgs_edu_digits($raw);return preg_match('/^([01][0-9]|2[0-3]):[0-5][0-9]$/D',$raw)?$raw:'';}
function dgs_school_class_options($year){$out=array();if(current_user_can('dgs_manage_education'))foreach(dgs_edu_classes($year) as $c)$out[$c->id]=$c;elseif(dgs_edu_role(get_current_user_id(),'dgs_student')){$c=dgs_hw_student_class($year);if($c)$out[$c->id]=$c;}elseif(dgs_edu_role(get_current_user_id(),'dgs_teacher'))foreach(dgs_grade_pairs($year) as $p){$c=dgs_edu_class($p->class_id);if($c)$out[$c->id]=$c;}return $out;}
function dgs_school_schedule($class_id){global $wpdb;$table=dgs_school_schedule_table();return $wpdb->get_row($wpdb->prepare("SELECT * FROM $table WHERE class_id=%d",$class_id));}
function dgs_school_teaching($class_id){global $wpdb;$e=dgs_edu_tables();$rows=$wpdb->get_results($wpdb->prepare("SELECT a.subject_id,a.teacher_id,s.title,u.display_name AS teacher FROM {$e['teaching']} a JOIN {$e['subjects']} s ON s.id=a.subject_id JOIN {$wpdb->users} u ON u.ID=a.teacher_id WHERE a.class_id=%d ORDER BY s.title",$class_id));$out=array();foreach($rows as $r)$out[(int)$r->subject_id]=$r;return $out;}
function dgs_school_schedule_save($d){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','ثبت برنامه فقط برای مدیر و معاون است.');$year=is_string($d['year']??null)?dgs_edu_year($d['year']):'';$class=is_scalar($d['class_id']??null)?dgs_edu_class($d['class_id']):null;if(!$class||$class->school_year!==$year)return dgs_edu_error('class','کلاس فعال همان سال را انتخاب کنید.');
 $periods=$d['periods']??null;$cells=$d['cells']??null;$events=$d['events']??array();if(!is_array($periods)||count($periods)!==6||!is_array($cells)||count($cells)>36||!is_array($events)||count($events)>10)return dgs_edu_error('input','ساختار برنامه معتبر نیست.');
 $pclean=array();$last='00:00';foreach(array_values($periods) as $p){if(!is_array($p)||!($start=dgs_school_clock($p['start']??null))||!($end=dgs_school_clock($p['end']??null))||$end<=$start||$start<$last)return dgs_edu_error('clock','ساعت زنگ‌ها باید ۲۴ساعته، به ترتیب و بدون هم‌پوشانی باشد.');$pclean[]=array('start'=>$start,'end'=>$end);$last=$end;}
 $teaching=dgs_school_teaching($class->id);$cclean=array();$used=array();foreach($cells as $c){if(!is_array($c))return dgs_edu_error('cell','خانه برنامه معتبر نیست.');foreach($c as $v)if(!is_scalar($v))return dgs_edu_error('cell','خانه برنامه معتبر نیست.');$day=(string)($c['day']??'');$slot=(string)($c['slot']??'');if(!in_array($day,array('0','1','2','3','4','5'),true)||!in_array($slot,array('0','1','2','3','4','5'),true)||isset($used[$day.':'.$slot]))return dgs_edu_error('cell','روز یا زنگ تکراری/نامعتبر است.');$used[$day.':'.$slot]=true;$subject=absint($c['subject_id']??0);$activity=sanitize_text_field((string)($c['activity']??''));$teacher=absint($c['teacher_id']??0);
 if($subject){if(!isset($teaching[$subject]))return dgs_edu_error('subject','درس باید به دبیر همین کلاس تخصیص یافته باشد.');$teacher=(int)$teaching[$subject]->teacher_id;$activity='';}elseif($activity==='')continue;elseif(dgs_edu_length($activity)>100||($teacher&&!dgs_edu_role($teacher,'dgs_teacher')))return dgs_edu_error('activity','عنوان فعالیت یا دبیر معتبر نیست.');$cclean[]=array('day'=>(int)$day,'slot'=>(int)$slot,'subject_id'=>$subject,'activity'=>$activity,'teacher_id'=>$teacher);}
 $eclean=array();foreach($events as $event){if(!is_array($event))return dgs_edu_error('event','آزمون حضوری معتبر نیست.');foreach($event as $v)if(!is_scalar($v))return dgs_edu_error('event','آزمون حضوری معتبر نیست.');$title=sanitize_text_field((string)($event['title']??''));if($title==='')continue;$at=dgs_quiz_date((string)($event['date']??''),(string)($event['time']??''),$year);$end=dgs_school_clock((string)($event['end']??''));$subject=absint($event['subject_id']??0);$type=(string)($event['type']??'class');if(!$at||!$end||$end<=wp_date('H:i',$at)||dgs_edu_length($title)>150||($subject&&!isset($teaching[$subject]))||!in_array($type,array('class','school'),true))return dgs_edu_error('event','عنوان، درس، تاریخ و ساعت آزمون حضوری را بررسی کنید.');$eclean[]=array('title'=>$title,'at'=>$at,'end'=>$end,'subject_id'=>$subject,'type'=>$type);}
 global $wpdb;$table=dgs_school_schedule_table();$old=dgs_school_schedule($class->id);$rev=$d['revision']??null;if(!is_scalar($rev)||!ctype_digit((string)$rev)||(int)$rev!==($old?(int)$old->revision:0))return dgs_edu_error('stale','برنامه هم‌زمان تغییر کرده؛ صفحه را تازه کنید.');
 // کنترل تداخل دبیر با برنامه کلاس‌های دیگر همین سال.
 $other=$wpdb->get_results($wpdb->prepare("SELECT x.* FROM $table x JOIN ".$wpdb->prefix."dgs_classes c ON c.id=x.class_id WHERE c.school_year=%s AND c.active=1 AND c.id<>%d",$year,$class->id));foreach($other as $plan){$op=json_decode($plan->periods,true);$ot=dgs_school_teaching($plan->class_id);foreach(json_decode($plan->cells,true)?:array() as $oc){$tid=$oc['subject_id']?(int)($ot[$oc['subject_id']]->teacher_id??0):(int)$oc['teacher_id'];if(!$tid||!isset($op[$oc['slot']]))continue;foreach($cclean as $c)if($c['teacher_id']===$tid&&$c['day']===$oc['day']&&$pclean[$c['slot']]['start']<$op[$oc['slot']]['end']&&$op[$oc['slot']]['start']<$pclean[$c['slot']]['end'])return dgs_edu_error('conflict','زمان یکی از دبیران با برنامه کلاس دیگری تداخل دارد.');}}
 $row=array('periods'=>wp_json_encode($pclean),'cells'=>wp_json_encode($cclean),'events'=>wp_json_encode($eclean),'revision'=>(int)$rev+1,'updated_by'=>get_current_user_id());if($old)$ok=$wpdb->update($table,$row,array('class_id'=>$class->id,'revision'=>(int)$rev));else{$row['class_id']=$class->id;$ok=$wpdb->insert($table,$row);}if(!$ok)return dgs_edu_error('write','برنامه ذخیره نشد یا هم‌زمان تغییر کرد.');dgs_edu_audit('timetable_save',$class->id);return 'برنامه هفتگی و تقویم آزمون‌ها ذخیره شد.';
}
function dgs_school_student_update($d){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','اجازه مدیریت ندارید.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','درخواست معتبر نیست.');$uid=absint($d['student_id']??0);if(!dgs_edu_role($uid,'dgs_student'))return dgs_edu_error('student','دانش‌آموز معتبر انتخاب کنید.');$name=sanitize_text_field((string)($d['name']??''));$phone=dgs_normalize_phone((string)($d['phone']??''));$guardian=(string)($d['guardian_phone']??'');$code=sanitize_text_field((string)($d['student_code']??''));if(!$name||dgs_edu_length($name)>100||!$phone||($guardian!==''&&!dgs_normalize_phone($guardian))||dgs_edu_length($code)>30)return dgs_edu_error('profile','نام، شماره تماس و کد دانش‌آموز را بررسی کنید.');$ok=wp_update_user(array('ID'=>$uid,'display_name'=>$name,'nickname'=>$name));if(is_wp_error($ok))return dgs_edu_error('write','ویرایش انجام نشد.');update_user_meta($uid,'_dgs_contact_phone',$phone);update_user_meta($uid,'_dgs_guardian_phone',$guardian===''?'':dgs_normalize_phone($guardian));update_user_meta($uid,'_dgs_student_code',$code);dgs_edu_audit('student_profile',$uid);return 'مشخصات ذخیره شد؛ نام کاربری و رمز تغییر نکرده‌اند.';
}
function dgs_school_assign_student($d){
 if(!current_user_can('dgs_manage_education'))return dgs_edu_error('access','اجازه مدیریت ندارید.');foreach($d as $v)if(!is_scalar($v))return dgs_edu_error('input','درخواست معتبر نیست.');$uid=absint($d['student_id']??0);$year=dgs_edu_year((string)($d['year']??''));$class=dgs_edu_class($d['class_id']??0);if(!dgs_edu_role($uid,'dgs_student')||!$year||!$class||$class->school_year!==$year)return dgs_edu_error('class','دانش‌آموز و کلاس همان سال معتبر باشند.');global $wpdb;$e=dgs_edu_tables();$old=$wpdb->get_row($wpdb->prepare("SELECT * FROM {$e['enrollments']} WHERE student_id=%d AND school_year=%s",$uid,$year));if($old&&(int)$old->class_id!==(int)$class->id&&($d['replace']??'')!=='1')return dgs_edu_error('replace','برای انتقال از کلاس قبلی تأیید انتقال را انتخاب کنید.');$row=array('class_id'=>$class->id);$ok=$old?$wpdb->update($e['enrollments'],$row,array('id'=>$old->id)): $wpdb->insert($e['enrollments'],array('student_id'=>$uid,'class_id'=>$class->id,'school_year'=>$year,'created_at'=>current_time('mysql')));if($ok===false)return dgs_edu_error('write','انتساب ثبت نشد.');dgs_edu_audit('student_transfer',$uid);return 'انتساب کلاس ثبت شد؛ سوابق قبلی نمره، حضور و غیاب و مالی حذف نشدند.';
}
add_action('admin_post_dgs_school',function(){
 if(($_SERVER['REQUEST_METHOD']??'')!=='POST'||!current_user_can('dgs_manage_education'))wp_die('دسترسی مجاز نیست.','',array('response'=>403));check_admin_referer('dgs_school','dgs_school_nonce');$d=wp_unslash($_POST);$op=is_string($d['operation']??null)?$d['operation']:'';$r=$op==='schedule'?dgs_school_schedule_save($d):($op==='profile'?dgs_school_student_update($d):($op==='assign'?dgs_school_assign_student($d):($op==='student_create'?dgs_school_student_create($d):($op==='import'?dgs_school_import($_FILES['roster_file']??null,$d):dgs_edu_error('operation','عملیات معتبر نیست.')))));$token=wp_generate_password(24,false,false);set_transient('dgs_edu_flash_'.get_current_user_id().'_'.$token,array('error'=>is_wp_error($r),'text'=>is_wp_error($r)?$r->get_error_message():$r),300);$year=is_string($d['year']??null)?dgs_edu_year($d['year']):'';wp_safe_redirect(add_query_arg(array('dg_tab'=>$op==='schedule'?'timetable':'education','dg_year'=>$year,'school_class'=>is_scalar($d['class_id']??null)?absint($d['class_id']):0,'dg_notice'=>$token),dgs_page_url('portal')),303);exit;
});
function dgs_school_upcoming($class_id,$year,$limit=10){
 global $wpdb;$q=dgs_quiz_tables();$e=dgs_edu_tables();$rows=$wpdb->get_results($wpdb->prepare("SELECT q.title,q.opens_at AS at,q.closes_at AS ends,s.title AS subject FROM {$q['quizzes']} q JOIN {$e['subjects']} s ON s.id=q.subject_id WHERE q.class_id=%d AND q.school_year=%s AND q.status='published' AND q.opens_at>%d ORDER BY q.opens_at LIMIT 30",$class_id,$year,time()));$out=array();foreach($rows as $r)$out[]=array('title'=>$r->title,'at'=>(int)$r->at,'end'=>wp_date('H:i',$r->ends),'subject'=>$r->subject,'type'=>'class');$plan=dgs_school_schedule($class_id);$subjects=dgs_school_teaching($class_id);if($plan)foreach(json_decode($plan->events,true)?:array() as $event)if($event['at']>time()){$event['subject']=$subjects[$event['subject_id']]->title??'—';$out[]=$event;}usort($out,function($a,$b){return $a['at']<=>$b['at'];});return array_slice($out,0,$limit);
}
function dgs_school_grade_series($year,$student=0){
 global $wpdb;$e=dgs_edu_tables();$g=dgs_grade_table();$args=array($year);$where='';if($student){if(!current_user_can('dgs_manage_education')&&get_current_user_id()!==$student)return array();$where=' AND g.student_id=%d';$args[]=$student;}
 elseif(!current_user_can('dgs_manage_education'))return array();return $wpdb->get_results($wpdb->prepare("SELECT g.period,AVG(g.score) AS average FROM $g g JOIN {$e['classes']} c ON c.id=g.class_id WHERE c.school_year=%s AND g.published=1 $where GROUP BY g.period ORDER BY g.period DESC LIMIT 3",$args));
}
